mapper.select:

       SELECT #{push} time,entrance_id area,service type,sum(sum) count
        FROM ntc_entrance_report
          WHERE report_time >= #{start}
          AND report_time < #{end}
          AND (
            service BETWEEN 16 AND 65
		    or service BETWEEN 256 AND 266
		     or service BETWEEN 512 AND 576
          )
		GROUP BY service , entrance_id
		ORDER BY count desc
		LIMIT 10;


SELECT #{push} time,url type,SUM(sum) count
FROM ntc_reject_url_statistic
  WHERE stat_time >= #{start}
  AND stat_time < #{end}
GROUP BY url
having trim(type)!=''
ORDER BY count desc
LIMIT 100;


SELECT #{push} time,url type,ip_addr ip,SUM(sum) count
   FROM ntc_reject_url_statistic
  WHERE stat_time >= #{start}
  AND stat_time < #{end}
   GROUP BY url,ip_addr
   having trim(type)!=''
   ORDER BY count desc
   LIMIT 100;


SELECT #{push} time ,website type ,sum(sum) count
FROM ntc_reject_website_statistic
  WHERE stat_time >= #{start}
  AND stat_time < #{end}
group by website
   having trim(type)!=''
ORDER BY count desc
LIMIT 100;


SELECT #{push} time,website type,ip_addr ip,sum count
    FROM ntc_reject_website_statistic
    WHERE stat_time >= #{start}
    AND stat_time < #{end}
    GROUP BY website ,ip_addr
    having trim(website)!=''
    ORDER BY count desc
    LIMIT 100;


        SELECT #{push} time,tag type ,SUM(sum) count
        FROM ntc_tag_report
          WHERE report_time >= #{start}
          AND report_time < #{end}
		  GROUP BY tag
		  ORDER BY count desc;


        SELECT  #{push} time,tag type ,SUM(sum) count
